<template>
  <UCard>
    <template #header><h3 class="font-semibold">{{ initial ? 'Event settings' : 'Create an event' }}</h3></template>
    <form class="event-form space-y-6" @submit.prevent="save">
      <UAlert v-if="error" color="error" :title="error" />
      <div class="grid gap-4 sm:grid-cols-2">
        <label class="sm:col-span-2">Event name<input v-model="form.name" required maxlength="250"></label>
        <label>Venue<input v-model="form.venue" maxlength="1000"></label>
        <label>Status<select v-model="form.status"><option v-for="status in statuses" :key="status" :value="status">{{ status }}</option></select></label>
        <label>Start date<input v-model="form.startDate" required type="date"></label>
        <label>End date<input v-model="form.endDate" required type="date" :min="form.startDate"></label>
        <label>Registration deadline<input v-model="form.registrationDeadline" required type="date" :max="form.startDate"></label>
        <label>Attendee details deadline<input v-model="form.detailsDeadline" type="date" :max="form.startDate"></label>
        <label class="sm:col-span-2">Description and inclusions<textarea v-model="form.description" rows="3" maxlength="10000" placeholder="Training, meals, accommodation, itinerary…" /></label>
      </div>
      <UAlert v-if="form.registrationMode === 'public'" color="info" title="Organization event" description="Share one invitation and registration link with anyone. Participants and payments stay in this event; no dojo student or guardian record is created." />
      <fieldset v-if="form.registrationMode === 'linked'"><legend class="mb-2 font-semibold">Eligible dojos</legend><p class="mb-3 text-sm text-slate-500">Legacy linked event. Scope is fixed after the first booking.</p><div class="flex flex-wrap gap-4"><label v-for="dojo in dojos || []" :key="dojo.id" class="flex items-center gap-2"><input v-model="form.dojoIds" type="checkbox" :value="dojo.id">{{ dojo.name }}</label></div></fieldset>
      <fieldset><legend class="mb-3 font-semibold">Capacity <span class="text-sm font-normal text-slate-500">— 0 means unlimited</span></legend><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label v-for="field in capacities" :key="field.key">{{ field.label }}<input v-model.number="form[field.key]" type="number" min="0" max="100000" required></label></div></fieldset>
      <fieldset><legend class="mb-3 font-semibold">Prices ({{ currency }})</legend><p class="mb-3 text-sm text-slate-500">Base rates apply per person. Optional transport and accommodation are added per attendee; use 0 when included. Existing bookings retain their agreed rates.</p><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><label v-for="field in prices" :key="field.key">{{ field.label }}<input v-model.number="form.prices[field.key]" type="number" min="0" step="0.01" required></label><label>Tax (%)<input v-model.number="taxPercent" type="number" min="0" max="100" step="0.01" required></label></div></fieldset>
      <div class="grid gap-4 sm:grid-cols-2"><label>Booking confirmation<select v-model="form.confirmationRule"><option value="staff">Staff approval</option><option value="deposit">After booking deposit</option><option value="full">After full payment</option></select></label><label v-if="form.confirmationRule === 'deposit'">Deposit per booking ({{ currency }})<input v-model.number="form.deposit" type="number" min="0.01" step="0.01" required></label></div>
      <fieldset><legend class="mb-3 font-semibold">Cost budget ({{ currency }}, including supplier tax)</legend><div class="grid gap-4 sm:grid-cols-3"><label>Fixed direct costs<input v-model.number="form.fixedBudget" type="number" min="0" step="0.01" required></label><label>Direct cost per attendee<input v-model.number="form.perPersonBudget" type="number" min="0" step="0.01" required></label><label>Other expenses / overhead<input v-model.number="form.overheadBudget" type="number" min="0" step="0.01" required></label></div></fieldset>
      <label class="block">Participation, consent and cancellation terms<textarea v-model="form.terms" rows="5" maxlength="20000" :required="form.status === 'open'" placeholder="Describe participation requirements, guardian consent, cancellation fees and refund rules." /></label>
      <label class="block">Instructions for registered families<textarea v-model="form.instructions" rows="4" maxlength="20000" placeholder="Packing list, pickup points, schedule and contact information" /></label>
      <fieldset class="space-y-3 rounded-xl border border-slate-200 p-4 dark:border-slate-800"><legend class="px-2 font-semibold">Photo and signed form</legend><label class="flex items-center gap-2"><input v-model="form.formSettings.requirePhoto" type="checkbox">Require a student photo on the online registration</label><label class="flex items-center gap-2"><input v-model="form.formSettings.requirePhysicalCopy" type="checkbox">Require the signed printed form before approval</label><label class="block">Instructions for the printed form<textarea v-model="form.formSettings.physicalCopyInstructions" rows="2" maxlength="2000" placeholder="Where and when to submit the signed copy" /></label></fieldset>
      <fieldset class="space-y-4 rounded-xl border border-slate-200 p-4 dark:border-slate-800"><legend class="px-2 font-semibold">Public form and organization-branded invitation</legend><p class="text-sm text-slate-500">The organization name and logo come from Organization settings. These fields customize this event only. Existing answers keep their original question labels when you edit the form.</p><div class="grid gap-4 sm:grid-cols-2"><label>Form title<input v-model="form.formSettings.title" maxlength="160" :placeholder="`${form.name || 'Event'} registration`"></label><label>Accent color<input v-model="form.formSettings.accentColor" type="color"></label><label class="sm:col-span-2">Introduction<textarea v-model="form.formSettings.introduction" rows="2" maxlength="3000" /></label><label class="sm:col-span-2">Privacy notice<textarea v-model="form.formSettings.privacyNotice" rows="2" maxlength="3000" /></label><label>Submit button text<input v-model="form.formSettings.submitLabel" required maxlength="80"></label><label class="sm:col-span-2">Message after submission<textarea v-model="form.formSettings.confirmationMessage" rows="2" maxlength="2000" /></label><label>Invitation heading<input v-model="form.formSettings.letterHeading" required maxlength="160"></label><label class="sm:col-span-2">Invitation body<textarea v-model="form.formSettings.letterBody" rows="5" maxlength="10000" placeholder="Write the invitation text. The generated PDF also includes the event dates, venue and registration link." /></label><label class="sm:col-span-2">Organizer contact details for the letter<textarea v-model="form.formSettings.contactText" rows="2" maxlength="1000" /></label></div><div class="flex items-center justify-between gap-3"><h4 class="font-medium">Additional registration questions</h4><UButton type="button" size="sm" variant="outline" :disabled="form.formSettings.questions.length >= 20" @click="addQuestion">Add question</UButton></div><div v-for="(question, index) in form.formSettings.questions" :key="question.id" class="space-y-3 rounded-lg border border-slate-200 p-3 dark:border-slate-700"><div class="grid gap-3 sm:grid-cols-2"><label>Question<input v-model="question.label" required maxlength="120"></label><label>Answer type<select v-model="question.type"><option value="text">Short text</option><option value="textarea">Long text</option><option value="select">Choose one</option><option value="checkbox">Checkbox</option><option value="date">Date</option></select></label><label class="sm:col-span-2">Help text<input v-model="question.help" maxlength="300"></label><label v-if="question.type === 'select'" class="sm:col-span-2">Options (one per line)<textarea :value="question.options.join('\n')" rows="3" @input="setOptions(question, $event)" /></label></div><div class="flex flex-wrap items-center gap-2"><label class="flex items-center gap-2"><input v-model="question.required" type="checkbox">Required</label><UButton type="button" size="xs" color="neutral" variant="ghost" :disabled="index === 0" @click="moveQuestion(Number(index), -1)">Move up</UButton><UButton type="button" size="xs" color="neutral" variant="ghost" :disabled="index === form.formSettings.questions.length - 1" @click="moveQuestion(Number(index), 1)">Move down</UButton><UButton type="button" size="xs" color="error" variant="ghost" @click="form.formSettings.questions.splice(index, 1)">Remove</UButton></div></div></fieldset>
      <div class="flex gap-3"><UButton type="submit" :loading="saving">{{ initial ? 'Save settings' : 'Create event' }}</UButton><UButton color="neutral" variant="ghost" @click="$emit('cancel')">Cancel</UButton></div>
    </form>
  </UCard>
</template>
<script setup lang="ts">
import { defaultEventFormSettings } from '#shared/types/events'
const props = defineProps<{ initial?: any, currency: string }>()
const emit = defineEmits(['saved', 'cancel'])
const { data: dojos } = await useFetch<any[]>('/api/dojos', { immediate: props.initial?.registrationMode === 'linked' })
const form = reactive<any>(props.initial ? structuredClone(toRaw(props.initial)) : { name: '', description: '', venue: '', startDate: '', endDate: '', registrationDeadline: '', detailsDeadline: '', status: 'draft', registrationMode: 'public', dojoIds: [], capacity: 0, bedCapacity: 0, outboundCapacity: 0, returnCapacity: 0, prices: { student: 0, parent: 0, transportOut: 0, transportReturn: 0, accommodation: 0, taxBps: 0 }, confirmationRule: 'staff', deposit: 0, terms: '', instructions: '', fixedBudget: 0, perPersonBudget: 0, overheadBudget: 0, formSettings: structuredClone(defaultEventFormSettings) })
form.formSettings ||= structuredClone(defaultEventFormSettings)
const statuses = ['draft', 'open', 'closed', 'completed', 'cancelled']
const capacities = [{ key: 'capacity', label: 'All attendees' }, { key: 'bedCapacity', label: 'Beds' }, { key: 'outboundCapacity', label: 'Outward bus seats' }, { key: 'returnCapacity', label: 'Return bus seats' }]
const prices = [{ key: 'student', label: 'Student base rate' }, { key: 'parent', label: 'Parent base rate' }, { key: 'transportOut', label: 'Outward transport' }, { key: 'transportReturn', label: 'Return transport' }, { key: 'accommodation', label: 'Accommodation' }]
const taxPercent = ref(form.prices.taxBps / 100)
if (props.initial) { for (const field of prices) form.prices[field.key] /= 100; for (const key of ['deposit', 'fixedBudget', 'perPersonBudget', 'overheadBudget']) form[key] /= 100 }
const saving = ref(false); const error = ref('')
function addQuestion() { form.formSettings.questions.push({ id: crypto.randomUUID(), label: '', type: 'text', required: false, help: '', options: [] }) }
function moveQuestion(index: number, direction: number) { const [question] = form.formSettings.questions.splice(index, 1); form.formSettings.questions.splice(index + direction, 0, question) }
function setOptions(question: any, event: Event) { question.options = (event.target as HTMLTextAreaElement).value.split(/\r?\n/).map(option => option.trim()).filter(Boolean) }
async function save() {
  saving.value = true; error.value = ''
  try {
    const body = { ...form, detailsDeadline: form.detailsDeadline || null, prices: { ...form.prices, taxBps: Math.round(taxPercent.value * 100) } }
    for (const field of prices) body.prices[field.key] = Math.round(Number(form.prices[field.key]) * 100)
    for (const key of ['deposit', 'fixedBudget', 'perPersonBudget', 'overheadBudget']) body[key] = Math.round(Number(form[key]) * 100)
    const result = await $fetch<any>(props.initial ? `/api/events/${props.initial.id}` : '/api/events', { method: props.initial ? 'PATCH' : 'POST', body })
    emit('saved', result)
  } catch (err: any) { error.value = err.data?.statusMessage || err.message } finally { saving.value = false }
}
</script>
<style scoped>
.event-form label { font-size: .875rem; font-weight: 500; }
.event-form input:not([type=checkbox]), .event-form select, .event-form textarea { display:block; width:100%; margin-top:.4rem; padding:.6rem .75rem; border:1px solid var(--ui-border); border-radius:.5rem; background:var(--ui-bg); color:var(--ui-text); font-weight:400; }
</style>
